package org.shiraz.mediaprobe;
import android.app.Activity;
import android.os.Bundle;
import android.os.Handler;
import android.widget.*;
import android.hardware.Camera;
import android.media.AudioRecord;
import android.media.AudioFormat;

/** Real hardware probe. Reports only dimensions/counts; never writes captured media. */
public final class ProbeActivity extends Activity {
 private TextView status;private Handler handler;private volatile boolean stopped,busy;
 private volatile AudioRecord microphone;private volatile Camera camera;
 @Override public void onCreate(Bundle state){super.onCreate(state);handler=new Handler();LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xffffffff);root.setPadding(16,20,16,20);TextView title=new TextView(this);title.setText("Shiraz real capture probe");title.setTextSize(22);title.setTextColor(0xff000000);root.addView(title);TextView note=new TextView(this);note.setText("This is a hardware test fixture, not Telegram. No camera images or microphone audio are saved.");note.setTextColor(0xff000000);root.addView(note);Button mic=new Button(this);mic.setText("Test microphone for 2 seconds");mic.setOnClickListener(new android.view.View.OnClickListener(){public void onClick(android.view.View view){request(1);}});mic.setBackgroundColor(0xffdddddd);mic.setTextColor(0xff000000);root.addView(mic);Button video=new Button(this);video.setText("Test camera frames");video.setOnClickListener(new android.view.View.OnClickListener(){public void onClick(android.view.View view){request(2);}});video.setBackgroundColor(0xffdddddd);video.setTextColor(0xff000000);root.addView(video);status=new TextView(this);status.setTextColor(0xff000000);status.setText("Ready. Each test requires app consent and macOS permission.");root.addView(status);setContentView(root);}
 private void request(int code){if(busy)return;requestPermissions(new String[]{code==1?"android.permission.RECORD_AUDIO":"android.permission.CAMERA"},code);}
 private void report(String value){handler.post(new Runnable(){public void run(){if(!stopped)status.setText(value);}});System.err.println("SHIRAZ_CAPTURE_PROBE "+value);}
 @Override public void onRequestPermissionsResult(final int code,String[] names,int[] grants){if(grants.length!=1||grants[0]!=0){report("App permission denied");return;}if(busy)return;busy=true;report("Waiting for macOS permission or hardware...");new Thread(new Runnable(){public void run(){try{if(code==1)testMicrophone();else testCamera();}catch(Throwable failure){report("FAILED: "+failure.getClass().getSimpleName()+": "+failure.getMessage());}finally{busy=false;}}},"Shiraz hardware probe").start();}
 private void testMicrophone(){int size=AudioRecord.getMinBufferSize(44100,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);AudioRecord record=new AudioRecord(1,44100,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,size);microphone=record;try{record.startRecording();byte[] bytes=new byte[8820];long samples=0,nonzero=0;long until=System.nanoTime()+2000000000L;while(!stopped&&System.nanoTime()<until){int count=record.read(bytes,0,bytes.length);if(count<0)throw new IllegalStateException("PCM read error "+count);for(int i=0;i+1<count;i+=2){samples++;if(bytes[i]!=0||bytes[i+1]!=0)nonzero++;}}if(stopped)return;if(samples<44100)throw new IllegalStateException("Insufficient hardware PCM frames");report("MICROPHONE_OK samples="+samples+" nonzero="+nonzero);}finally{record.release();microphone=null;}}
 private void testCamera()throws Exception{Camera opened=Camera.open();camera=opened;try{final Object lock=new Object();final int[] count={0};final int[] size={0,0};Camera.Size dimensions=opened.getParameters().getPreviewSize();size[0]=dimensions.width;size[1]=dimensions.height;opened.setPreviewCallback(new Camera.PreviewCallback(){public void onPreviewFrame(byte[] bytes,Camera source){synchronized(lock){if(bytes.length==size[0]*size[1]*3/2){count[0]++;lock.notifyAll();}}}});opened.startPreview();synchronized(lock){long until=System.currentTimeMillis()+5000;while(!stopped&&count[0]<3&&System.currentTimeMillis()<until)lock.wait(100);}if(stopped)return;if(count[0]<3)throw new IllegalStateException("No complete NV21 camera callbacks");report("CAMERA_OK width="+size[0]+" height="+size[1]+" callbacks="+count[0]);}finally{opened.release();camera=null;}}
 @Override public void onStop(){stopped=true;AudioRecord mic=microphone;if(mic!=null)mic.release();Camera video=camera;if(video!=null)video.release();super.onStop();}
}
